using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Marketplace;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;using OrcaFacil.Persistence.Marketplace;
namespace OrcaFacil.Web.Pages.Marketplace;
[Authorize] public sealed class InstallationsModel(OrcaFacilDbContext db,ICurrentAccountService current,PackageRollbackService rollback):PageModel{public IReadOnlyList<Row> Items{get;private set;}=[];public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid a||!await current.HasPermissionAsync(MarketplacePermissions.View,ct))return Forbid();Items=await(from i in db.MarketplacePackageInstallations.AsNoTracking()join p in db.MarketplacePackages.AsNoTracking()on i.PackageId equals p.Id join v in db.MarketplacePackageVersions.AsNoTracking()on i.PackageVersionId equals v.Id where i.AccountId==a&&!i.IsDeleted select new Row(i.Id,p.Name,v.Version,i.Status,i.CompletedAt,db.MarketplacePackageInstallationItems.Count(x=>x.InstallationId==i.Id&&x.Status=="Applied"))).OrderByDescending(x=>x.CompletedAt).ToListAsync(ct);return Page();}public async Task<IActionResult>OnPostRollbackAsync(Guid id,string confirmation,CancellationToken ct){if(current.AccountId is not Guid a||!await current.HasPermissionAsync(MarketplacePermissions.Rollback,ct))return Forbid();if(confirmation!="DESATIVAR"){TempData["Error"]="Digite DESATIVAR para confirmar o rollback.";return RedirectToPage();}await rollback.RollbackAsync(a,current.UserId,id,true,ct);TempData["Success"]="Rollback concluído. Os dados operacionais foram preservados.";return RedirectToPage();}public sealed record Row(Guid Id,string Name,string Version,PackageInstallationStatus Status,DateTime? CompletedAt,int Applied);}
